using System.Text.Json;
using Refyntra.Tests.Infrastructure;

namespace Refyntra.Tests;

/// <summary>
/// Rename of a DbContext / entity referenced from EF Core migrations (protocol 1.5, PrepareParams.generatedEdits).
/// (A) "efMigrations": only the references to the symbol are renamed in proven EF migration/snapshot files, never
/// strings; (B) "none": the migrations are left unchanged and the plan is limited with an explicit warning. Other
/// generated code is still refused. Each test works on its own copy of the EfCore fixture, with the
/// &lt;auto-generated&gt; header EF Core writes into its files.
/// </summary>
public sealed class EfMigrationRenameTests
{
    private static async Task<(TestClient c, string dir)> OpenAsync(Action<string>? beforeOpen = null)
    {
        var sln = await Fixtures.CopyAsync("EfCore", "EfCore.sln");
        var dir = Path.GetDirectoryName(sln)!;
        // As EF Core writes them: every migration file starts with an <auto-generated> header.
        foreach (var f in Directory.EnumerateFiles(Path.Combine(dir, "EfCore.Api", "Migrations"), "*.cs"))
            File.WriteAllText(f, "// <auto-generated />\n" + File.ReadAllText(f));
        beforeOpen?.Invoke(dir);
        var c = TestClient.InProcess();
        await c.InitializeAsync();
        var status = await c.OpenAsync(sln);
        Assert.Equal("Ready", status.GetProperty("state").GetString());
        return (c, dir);
    }

    private static string Api(string dir, params string[] parts) => Path.GetFullPath(Path.Combine(new[] { dir, "EfCore.Api" }.Concat(parts).ToArray()));

    private static async Task<JsonElement> PrepareAsync(TestClient c, string file, string needle, int offset, string newName, string? generatedEdits)
    {
        var snap = await c.BarrierAsync();
        var s = await c.SymbolAtTextAsync(snap, file, needle, offset);
        object p = generatedEdits == null
            ? new { traceId = "t", workspaceId = c.WorkspaceId, snapshotId = snap, actionId = "csharp.rename", symbolId = s.GetProperty("symbolId").GetString(), newName }
            : new { traceId = "t", workspaceId = c.WorkspaceId, snapshotId = snap, actionId = "csharp.rename", symbolId = s.GetProperty("symbolId").GetString(), newName, generatedEdits };
        return await c.RequestAsync("refactor/prepare", p);
    }

    private static JsonElement Prepared(JsonElement r)
    {
        Assert.True(r.GetProperty("kind").GetString() == "prepared", r.ToString());
        return r.GetProperty("plan");
    }

    private static List<JsonElement> TextChanges(JsonElement plan) =>
        plan.GetProperty("writeSet").EnumerateArray().Where(w => w.GetProperty("kind").GetString() == "text").ToList();

    private static string FileOf(JsonElement change) => Uri.UnescapeDataString(change.GetProperty("uri").GetString()!.Split('/').Last());

    private static List<string> Limitations(JsonElement plan) => plan.GetProperty("limitations").EnumerateArray().Select(l => l.GetString()!).ToList();

    /// <summary>The text after applying the edits of a planned change (edits are ordered and non-overlapping).</summary>
    private static string Apply(string text, JsonElement change)
    {
        int Offset(JsonElement pos)
        {
            var at = 0;
            for (var i = 0; i < pos.GetProperty("line").GetInt32(); i++) at = text.IndexOf('\n', at) + 1;
            return at + pos.GetProperty("character").GetInt32();
        }
        var result = new System.Text.StringBuilder();
        var last = 0;
        foreach (var e in change.GetProperty("edits").EnumerateArray())
        {
            var start = Offset(e.GetProperty("range").GetProperty("start"));
            result.Append(text, last, start - last).Append(e.GetProperty("newText").GetString());
            last = Offset(e.GetProperty("range").GetProperty("end"));
        }
        return result.Append(text, last, text.Length - last).ToString();
    }

    [Theory]
    [InlineData("efMigrations")]
    [InlineData(null)] // absent = the default (efMigrations)
    public async Task Context_rename_with_migrations_edits_only_symbol_references_in_proven_migration_files(string? mode)
    {
        var (c, dir) = await OpenAsync();
        await using var _ = c;
        var plan = Prepared(await PrepareAsync(c, Api(dir, "Data", "ShopDbContext.cs"), "class ShopDbContext", 6, "StoreDbContext", mode));
        Assert.Equal("valid", plan.GetProperty("validation").GetProperty("status").GetString());
        Assert.Equal("passed", plan.GetProperty("validation").GetProperty("compilationDelta").GetString());

        var ef = plan.GetProperty("efMigrations");
        Assert.Equal("efMigrations", ef.GetProperty("mode").GetString());
        var efFiles = ef.GetProperty("files").EnumerateArray().Select(f => Uri.UnescapeDataString(f.GetString()!.Split('/').Last())).OrderBy(x => x).ToList();
        Assert.Equal(new[] { "20250101000000_Initial.Designer.cs", "ShopDbContextModelSnapshot.cs" }, efFiles);

        var migrationChanges = TextChanges(plan).Where(ch => efFiles.Contains(FileOf(ch))).ToList();
        Assert.Equal(2, migrationChanges.Count);
        foreach (var ch in migrationChanges)
        {
            // The result is the original with exactly typeof(ShopDbContext) renamed: strings and class names unchanged.
            var text = File.ReadAllText(Api(dir, "Migrations", FileOf(ch)));
            var expected = text.Replace("typeof(ShopDbContext)", "typeof(StoreDbContext)");
            Assert.NotEqual(text, expected);
            Assert.Equal(expected.Replace("\r\n", "\n"), Apply(text, ch).Replace("\r\n", "\n"));
        }
        var limits = Limitations(plan);
        Assert.Contains(limits, l => l.StartsWith("EF Core migrations (generated by EF): in 20250101000000_Initial.Designer.cs, ShopDbContextModelSnapshot.cs only the code references to ShopDbContext are renamed", StringComparison.Ordinal));
        Assert.Contains(limits, l => l.Contains("keep their names (ShopDbContextModelSnapshot)"));
        Assert.DoesNotContain(limits, l => l.StartsWith("The project will not build", StringComparison.Ordinal));

        var rv = await c.RevalidateAsync(await c.BarrierAsync(), plan.GetProperty("planId").GetString()!);
        Assert.Equal("valid", rv.GetProperty("status").GetString());
        // Read set: the migration files are fingerprinted like every other source file of the closure.
        Assert.Contains(plan.GetProperty("readSet").EnumerateArray(), r => r.GetProperty("input").GetString()!.EndsWith("ShopDbContextModelSnapshot.cs", StringComparison.Ordinal));
    }

    [Fact]
    public async Task Context_rename_without_migrations_leaves_them_unchanged_and_is_limited_with_the_build_warning()
    {
        var (c, dir) = await OpenAsync();
        await using var _ = c;
        var plan = Prepared(await PrepareAsync(c, Api(dir, "Data", "ShopDbContext.cs"), "class ShopDbContext", 6, "StoreDbContext", "none"));
        Assert.Equal("limited", plan.GetProperty("validation").GetProperty("status").GetString());
        Assert.Equal("failed", plan.GetProperty("validation").GetProperty("compilationDelta").GetString());
        Assert.Equal("none", plan.GetProperty("efMigrations").GetProperty("mode").GetString());
        Assert.Equal(2, plan.GetProperty("efMigrations").GetProperty("files").GetArrayLength());
        Assert.DoesNotContain(TextChanges(plan), ch => FileOf(ch).Contains("Snapshot") || FileOf(ch).Contains("Designer"));
        Assert.Contains(TextChanges(plan), ch => FileOf(ch) == "ShopDbContext.cs");
        Assert.Contains(Limitations(plan), l => l.StartsWith("The project will not build until the migrations are updated: 20250101000000_Initial.Designer.cs, ShopDbContextModelSnapshot.cs still reference ShopDbContext", StringComparison.Ordinal));

        var rv = await c.RevalidateAsync(await c.BarrierAsync(), plan.GetProperty("planId").GetString()!);
        Assert.Equal("limited", rv.GetProperty("status").GetString());
        Assert.Contains("will not build", rv.GetProperty("message").GetString());
    }

    [Theory]
    [InlineData("efMigrations")]
    [InlineData("none")]
    public async Task Other_generated_code_is_still_refused(string mode)
    {
        var (c, dir) = await OpenAsync(d => File.WriteAllText(Api(d, "Data", "ShopRegistry.g.cs"),
            "namespace EfCore.Api.Data;\n\ninternal static class ShopRegistry\n{\n    public static System.Type Context => typeof(ShopDbContext);\n}\n"));
        await using var _ = c;
        var r = await PrepareAsync(c, Api(dir, "Data", "ShopDbContext.cs"), "class ShopDbContext", 6, "StoreDbContext", mode);
        Assert.Equal("unavailable", r.GetProperty("kind").GetString());
        Assert.Equal("GeneratedCode", r.GetProperty("reasonCode").GetString());
        Assert.Contains("ShopRegistry.g.cs", r.GetProperty("message").GetString());
    }

    [Fact]
    public async Task Look_alike_DbContext_attribute_is_not_an_EF_migration()
    {
        var (c, dir) = await OpenAsync(d => File.WriteAllText(Api(d, "Data", "FakeSnapshot.cs"),
            "// <auto-generated />\nnamespace Fake\n{\n    internal sealed class DbContextAttribute : System.Attribute { public DbContextAttribute(System.Type t) { } }\n" +
            "    [DbContext(typeof(EfCore.Api.Data.ShopDbContext))]\n    internal sealed class FakeSnapshot { }\n}\n"));
        await using var _ = c;
        var r = await PrepareAsync(c, Api(dir, "Data", "ShopDbContext.cs"), "class ShopDbContext", 6, "StoreDbContext", "efMigrations");
        Assert.Equal("GeneratedCode", r.GetProperty("reasonCode").GetString());
        Assert.Contains("FakeSnapshot.cs", r.GetProperty("message").GetString());
    }

    [Fact]
    public async Task Entity_named_only_in_snapshot_strings_keeps_the_strings_and_says_so()
    {
        var (c, dir) = await OpenAsync();
        await using var _ = c;
        var snapshot = File.ReadAllText(Api(dir, "Migrations", "ShopDbContextModelSnapshot.cs"));
        var plan = Prepared(await PrepareAsync(c, Path.Combine(dir, "EfCore.Domain", "Entities.cs"), "class Order", 6, "PurchaseOrder", "efMigrations"));
        Assert.Equal("valid", plan.GetProperty("validation").GetProperty("status").GetString());
        Assert.False(plan.TryGetProperty("efMigrations", out var efm) && efm.ValueKind == JsonValueKind.Object);
        Assert.DoesNotContain(TextChanges(plan), ch => FileOf(ch).Contains("Snapshot") || FileOf(ch).Contains("Designer"));
        Assert.Contains(Limitations(plan), l => l.Contains("keep the old name as text: \"EfCore.Domain.Order\"") && l.Contains("ShopDbContextModelSnapshot.cs")
            && l.Contains("next migration you add may contain changes"));
        Assert.Equal(snapshot, File.ReadAllText(Api(dir, "Migrations", "ShopDbContextModelSnapshot.cs")));
    }
}
